import json

with open('/root/DATA/products/CoachForce.json', 'r') as f:
    data = json.load(f)

# Get the Market Research Report meeting transcript
if 'meeting_transcripts' in data:
    for meeting in data['meeting_transcripts']:
        if meeting.get('document_type') == 'Market Research Report' and meeting.get('id') == 'CoFoAIX_planning_1':
            transcript = meeting.get('transcript', '')
            # Look for key reviewers or reviewers mentions
            if 'reviewer' in transcript.lower() or 'review' in transcript.lower():
                lines = transcript.split('\n')
                for i, line in enumerate(lines):
                    if 'reviewer' in line.lower():
                        # Print context around the mention
                        start = max(0, i-2)
                        end = min(len(lines), i+3)
                        print('\n'.join(lines[start:end]))
                        print("-" * 80)
EOF
